const NARRATION_TEXT={"protein-0": "Nel nucleo, un gene del DNA viene trascritto in un messaggio di RNA. La cellula può così utilizzare l'informazione genetica senza spostare il DNA fuori dal nucleo.", "protein-1": "Il messaggio di RNA viene maturato e attraversa un poro dell'involucro nucleare. Una volta nel citoplasma, può essere letto da un ribosoma.", "protein-2": "Il ribosoma legge il messaggio e comincia a unire gli amminoacidi. Per la proteina destinata alla secrezione che seguiamo qui, il complesso viene indirizzato verso il reticolo endoplasmatico rugoso.", "protein-3": "La catena proteica nascente entra nel reticolo, dove inizia a ripiegarsi e può subire modifiche. La sua forma contribuirà alla funzione che svolgerà.", "protein-4": "Attraverso il trasporto vescicolare, la proteina raggiunge l'apparato di Golgi. Qui può essere ulteriormente modificata e smistata verso la sua destinazione.", "protein-5": "Una vescicola si fonde con la membrana plasmatica e libera il contenuto all'esterno: è l'esocitosi. Ricorda che molte altre proteine restano nella cellula e seguono percorsi diversi.", "energy": "Nel mitocondrio la catena respiratoria pompa protoni verso lo spazio tra le due membrane. I protoni rientrano nella matrice attraverso l'enzima a ti pi sintasi, che permette di produrre a ti pi da adenosina difosfato e fosfato. L'ossigeno accetta gli elettroni alla fine della catena. Varia le due risorse: l'indice è qualitativo. Anche altre vie cellulari producono a ti pi.", "osmosis": "L'osmosi è il movimento dell'acqua attraverso una membrana selettivamente permeabile. In un mezzo ipotonico, l'acqua tende a entrare nella cellula; in uno ipertonico tende a uscire. In isotonia l'acqua continua a muoversi nei due sensi, senza flusso netto. Nella cellula vegetale, la parete limita l'espansione e contribuisce al turgore. La forma visualizzata è una semplificazione.", "photo": "Nei cloroplasti, le reazioni dipendenti dalla luce avvengono nelle membrane dei tilacoidi. L'energia luminosa, insieme all'acqua, permette di formare ossigeno e di produrre a ti pi e enne a di pi acca. Nello stroma, il ciclo di Calvin utilizza anidride carbonica e queste molecole per formare composti organici. Cambia luce e anidride carbonica: l'indice è un modello qualitativo, non una previsione sperimentale.", "mitosis-0": "Prima che inizi la divisione mitotica, durante l'interfase, la cellula cresce e duplica il proprio DNA. Ogni cromosoma duplicato possiede due cromatidi fratelli. La duplicazione avviene nell'interfase e precede la separazione dei cromosomi.", "mitosis-1": "Durante profase e prometafase, i cromosomi si condensano, il fuso mitotico si organizza e l'involucro nucleare si disgrega. I microtubuli del fuso si collegano ai cromosomi.", "mitosis-2": "In metafase, i cromosomi si dispongono nella regione centrale della cellula. I cromatidi fratelli sono collegati ai microtubuli diretti verso poli opposti.", "mitosis-3": "In anafase, i cromatidi fratelli si separano e si spostano verso poli opposti. Da questo momento ciascun cromatide separato è considerato un cromosoma.", "mitosis-4": "In telofase, i cromosomi raggiungono i poli e cominciano a decondensarsi. Intorno a ciascun gruppo si riforma un involucro nucleare.", "mitosis-5": "La citodieresi separa il citoplasma e completa la divisione. In questa cellula animale si forma un solco di divisione; nelle cellule vegetali, invece, si forma una piastra cellulare.", "stress": "La cellula può reagire a condizioni sfavorevoli, per esempio a un aumento della temperatura. Uno stress moderato può attivare meccanismi di protezione e riparazione; se intenso o prolungato può alterare la struttura e la funzione delle proteine. Muovi il cursore e osserva il modello: le soglie e le risposte non sono misure biologiche, e il tempo di esposizione conta nelle cellule reali.", "protein-2-bloccata": "Il messaggio raggiunge il ribosoma. In questo modello la traduzione è stata bloccata: la catena proteica non viene prodotta e il percorso si arresta."};
let three=null;
const clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
const setText=(id,str)=>{const el=$(id);if(el)el.textContent=str};
function updateOrgan(){const o=ORGAN[state.organ];if(!o)return;for(const [id,prop] of [['organSymbol','symbol'],['organType','type'],['organName','name'],['organDescription','description'],['organRole','role'],['organObserve','observe']])setText(id,o[prop]);const keys=state.cell==='animal'?organAnimal:organPlant;setText('organId',`ORG. ${String(keys.indexOf(state.organ)+1).padStart(2,'0')}`);state.explored[state.cell].add(state.organ);setText('exploredCount',`${state.explored[state.cell].size} / ${keys.length}`);all('.organ-chip').forEach(b=>b.classList.toggle('selected',b.dataset.organ===state.organ));}
function showOrgan(key,focus=false){if(!ORGAN[key])return;state.organ=key;updateOrgan();if(three){three.highlight(key);if(focus)three.focus(key)}}
function refreshOrganList(){const keys=state.cell==='animal'?organAnimal:organPlant;$('organList').innerHTML='';for(const key of keys){const b=document.createElement('button');b.className='organ-chip';b.type='button';b.dataset.organ=key;b.textContent=ORGAN[key].name;b.addEventListener('click',()=>showOrgan(key,true));$('organList').append(b)}if(!keys.includes(state.organ))state.organ='nucleus';updateOrgan()}
function setCell(cell){if((state.experiment==='photo'&&cell==='animal')||(state.experiment==='mitosis'&&cell==='plant'))setExperiment('protein',false);if(cell!==state.cell){state.cell=cell;state.prediction=null}all('.organism-btn').forEach(b=>b.classList.toggle('active',b.dataset.cell===cell));setText('modelLabel',cell==='animal'?'CELLULA ANIMALE':'CELLULA VEGETALE');setText('statusText',cell==='animal'?'EUCARIOTE / CELLULA ANIMALE':'EUCARIOTE / CELLULA VEGETALE');refreshOrganList();if(three)three.setCell(cell);if(state.experiment==='osmosis')updateOsmosis();}
function setExperiment(mode,scroll=true){
 stopVoice();stopAutoplay();stopDivision();
 if(mode==='photo'&&state.cell!=='plant'){state.experiment='protein';setCell('plant')}
 if(mode==='mitosis'&&state.cell!=='animal'){state.experiment='protein';setCell('animal')}
 state.experiment=mode;$('divisionInfo').hidden=mode!=='mitosis';document.querySelector('.inspection').classList.toggle('division-active',mode==='mitosis');
 const configs={protein:{k:'ESPERIENZA 01 / PERCORSO ANIMATO',title:'La fabbrica delle proteine',indicator:'SEQUENZA GUIDATA',scene:'SINTESI PROTEICA'},energy:{k:'ESPERIENZA 02 / SIMULAZIONE',title:'L’energia della cellula',indicator:'MODIFICA UNA VARIABILE',scene:'METABOLISMO ENERGETICO'},osmosis:{k:'ESPERIENZA 03 / SIMULAZIONE',title:'Membrana e osmosi',indicator:'FORMULA UNA PREVISIONE',scene:'OSMOSI'},photo:{k:'ESPERIENZA 04 / SIMULAZIONE',title:'La fotosintesi',indicator:'LUCE E CO₂',scene:'FOTOSINTESI'},mitosis:{k:'ESPERIENZA 05 / PERCORSO ANIMATO',title:'La divisione cellulare',indicator:'SEQUENZA GUIDATA',scene:'MITOSI E CITODIERESI'},stress:{k:'ESPERIENZA 06 / SIMULAZIONE',title:'La cellula sotto stress',indicator:'ESPLORA LA RISPOSTA',scene:'STRESS TERMICO'}};
 const c=configs[mode];setText('labKicker',c.k);setText('labTitle',c.title);setText('labIndicator',c.indicator);setText('sceneModeLabel',c.scene);
 all('.experience-card[data-experience]').forEach(b=>b.classList.toggle('active',b.dataset.experience===mode));for(const name of ['protein','energy','osmosis','photo','mitosis','stress'])$(name+'Controls').hidden=name!==mode;
 if(three)three.setExperiment(mode);
 if(mode==='protein')updateProteinStep();else if(mode==='energy'){updateEnergy();showOrgan('mitochondria',true)}else if(mode==='osmosis')updateOsmosis();else if(mode==='photo'){updatePhoto();showOrgan('chloroplast',true)}else if(mode==='mitosis'){divisionStep=0;renderDivision()}else if(mode==='stress'){updateStress();showOrgan('nucleus',true)}
 if(mode!=='protein'&&mode!=='mitosis')setText('sceneCaption','Modello illustrativo · le animazioni rappresentano tendenze qualitative');
 setText('voiceTranscript',NARRATION_TEXT[currentVoiceKey()]||'');
 if(scroll)$('labPanel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});
}
function updateProteinStep(){const s=proteinSequence[state.proteinStep];setText('labStepCount',`FASE ${String(state.proteinStep+1).padStart(2,'0')} / 06`);setText('labStepTitle',s.title);setText('labExplanation',!state.translation&&state.proteinStep===2?'Il messaggio raggiunge il ribosoma. Nel modello la traduzione è bloccata: la catena proteica non viene prodotta.':s.description);$('labInsight').querySelector('p').textContent=s.insight;$('timelineFill').style.width=`${state.proteinStep/5*100}%`;const btn=$('prevStep');btn.disabled=state.proteinStep===0;setText('voiceTranscript',NARRATION_TEXT[state.proteinStep===2&&!state.translation?'protein-2-bloccata':`protein-${state.proteinStep}`]||'');setText('playSteps',state.playing?'Ⅱ Metti in pausa':'▶ Avvia automaticamente');if(three){three.proteinStage(state.proteinStep);three.focus(s.organ)}setText('sceneCaption',`FASE ${state.proteinStep+1}/6 · ${s.title}`);}
function stopAutoplay(){if(state.timer)clearInterval(state.timer);state.timer=null;state.playing=false;setText('playSteps','▶ Avvia automaticamente');}
function nextProteinStep(direction=1){if(state.experiment!=='protein')return;const next=clamp(state.proteinStep+direction,0,5);if(!state.translation&&next>=3){setText('proteinVariableResult','Traduzione bloccata nel modello: il percorso della proteina si arresta al ribosoma.');return}state.proteinStep=next;updateProteinStep();}
function toggleAutoplay(){if(state.playing){stopAutoplay();return;}if(state.proteinStep===5)state.proteinStep=0;state.playing=true;updateProteinStep();state.timer=setInterval(()=>{if(state.proteinStep>=5||(!state.translation&&state.proteinStep>=2)){stopAutoplay();if(!state.translation)setText('proteinVariableResult','Traduzione bloccata nel modello: il percorso della proteina si arresta al ribosoma.');return}state.proteinStep++;updateProteinStep()},Number($('proteinSpeed').value))}
function setNarrative(title,description,insight){setText('labStepCount','OSSERVA E SPERIMENTA');setText('labStepTitle',title);setText('labExplanation',description);$('labInsight').querySelector('p').textContent=insight;}
function updateEnergy(){const o=Number($('oxygenSlider').value);state.oxygen=o;const adp=Number($('adpSlider').value);state.adp=adp;const index=Math.round(100*Math.min(o/100,adp/100));setText('adpValue',adp+'%');$('atpDiagram').querySelector('.proton-flow').style.animationDuration=(2/Math.max(.12,index/100))+'s';$('atpDiagram').querySelector('.proton-flow').style.animationPlayState=index===0?'paused':'running';setText('atpMechanism',index===0?'Nel modello il flusso illustrato e la sintesi si arrestano.':'Nel modello il flusso illustrato e la sintesi rallentano quando la variabile limitante diminuisce.');setText('oxygenValue',o+'%');setText('energyIndex',index+' / 100');$('energyFill').style.width=index+'%';const msg=adp<15?'Con poco ADP e fosfato disponibili, il modello limita la sintesi di ATP anche se l’ossigeno è presente.':o<15?'In marcata carenza di ossigeno, la fosforilazione ossidativa è molto limitata. La glicolisi può continuare, ma non compensa pienamente in tutte le cellule.':o<50?'Con meno ossigeno, la capacità di sostenere la fosforilazione ossidativa diminuisce nel modello. Le risposte reali dipendono dal tipo cellulare.':'Con ossigeno disponibile, la catena respiratoria può sostenere la fosforilazione ossidativa mitocondriale.';setText('energyResult',msg);setNarrative('Che cosa cambia se manca ossigeno?',"Modifica ossigeno e disponibilità di ADP e osserva lo schema della membrana interna. L'ossigeno accetta gli elettroni alla fine della catena; il gradiente di protoni alimenta l'ATP sintasi.",'Un indice più basso significa una tendenza nel nostro modello, non una misurazione di molecole di ATP.');if(three)three.setOxygen(index);}
function updateOsmosis(){const c=Number($('soluteSlider').value);state.solute=c;setText('soluteValue',c+'%');const direction=c<47?'entra':c>53?'esce':'equilibrio';setText('osmosisState',direction==='entra'?'MEZZO IPOTONICO':direction==='esce'?'MEZZO IPERTONICO':'ISOTONIA');const result=direction==='entra'?('L’acqua ha una tendenza netta a entrare. '+(state.cell==='plant'?'La parete limita l’espansione, favorendo il turgore.':'La cellula animale tende ad aumentare di volume.')):direction==='esce'?('L’acqua ha una tendenza netta a uscire. '+(state.cell==='plant'?'Può comparire plasmolisi: la membrana si ritira dalla parete.':'La cellula animale tende a ridursi di volume.')):'L’acqua continua a spostarsi nei due sensi: non c’è un flusso netto.';setText('osmosisResult',result);setNarrative('L’acqua attraversa la membrana',"Modifica idealmente la concentrazione di soluti osmoticamente efficaci all'esterno. Osserva il flusso netto d'acqua e il cambiamento del volume cellulare.",'In isotonia le molecole non diventano immobili: entrano ed escono, in media, in ugual misura.');const p=state.prediction;all('#osmPredict button').forEach(b=>b.classList.toggle('selected',b.dataset.predict===p));if(p){const right=p===direction;$('labInsight').querySelector('p').textContent=(right?'Previsione corretta. ':'Rivedi la previsione. ')+result}if(three)three.setSolute(c);}
function renderQuiz(){const i=state.quizIndex;if(i>=quiz.length){$('quizQuestion').textContent=`Missione conclusa: ${state.score} risposte corrette su ${quiz.length}.`;$('quizAnswers').innerHTML='';setText('quizFeedback',state.score>=5?'Hai collegato bene strutture e funzioni.':'Riguarda le esperienze, poi riprova: ogni errore rivela un collegamento da chiarire.');$('quizNext').disabled=false;$('quizNext').textContent='↻ Ricomincia la sfida';setText('quizProgress',`${quiz.length} / ${quiz.length}`);$('quizProgressBar').style.width='100%';return}const q=quiz[i];$('quizQuestion').textContent=q.q;$('quizAnswers').innerHTML='';setText('quizFeedback','');state.quizAnswered=false;$('quizNext').disabled=true;$('quizNext').textContent=i===quiz.length-1?'Vedi il risultato →':'Prossima domanda →';setText('quizProgress',`${i} / ${quiz.length}`);$('quizProgressBar').style.width=`${i/quiz.length*100}%`;q.a.forEach((ans,n)=>{const b=document.createElement('button');b.textContent=String.fromCharCode(65+n)+'.  '+ans;b.type='button';b.addEventListener('click',()=>{if(state.quizAnswered)return;state.quizAnswered=true;state.score+=n===q.c?1:0;all('#quizAnswers button').forEach((btn,j)=>{btn.disabled=true;btn.classList.toggle('correct',j===q.c);btn.classList.toggle('wrong',j===n&&n!==q.c)});$('quizFeedback').textContent=(n===q.c?'Esatto. ':'Non proprio. ')+q.why;$('quizNext').disabled=false;});$('quizAnswers').append(b)});}
all('.organism-btn').forEach(b=>b.addEventListener('click',()=>setCell(b.dataset.cell)));
all('.experience-card[data-experience]').forEach(b=>b.addEventListener('click',()=>setExperiment(b.dataset.experience)));
