$('oxygenSlider').addEventListener('input',updateEnergy);$('adpSlider').addEventListener('input',updateEnergy);$('proteinSpeed').addEventListener('input',()=>{if(state.playing){stopAutoplay();toggleAutoplay()}});$('translationSwitch').addEventListener('change',e=>{stopVoice();state.translation=e.target.checked;setText('proteinVariableResult',state.translation?'Traduzione attiva nel modello.':'Traduzione bloccata nel modello: la sequenza si ferma al ribosoma.');if(!state.translation&&state.proteinStep>2)state.proteinStep=2;if(state.experiment==='protein')updateProteinStep()});$('soluteSlider').addEventListener('input',()=>{state.prediction=null;updateOsmosis()});
all('#osmPredict button').forEach(b=>b.addEventListener('click',()=>{state.prediction=b.dataset.predict;updateOsmosis()}));
