    for(let i=0;i<waterParticles.length;i++){let p=waterParticles[i],active=currentExperiment==='osmosis';p.mesh.visible=active;if(!active)continue;const a=p.lat,rx=currentCell==='plant'?2.26:2.4,ry=currentCell==='plant'?1.67:1.88;const outward=new T.Vector3(Math.cos(a),Math.sin(a),.10*Math.sin(p.phase));const f=Math.abs(currentSolute-50)<=3?0:(currentSolute-50)/50;const outwardCount=Math.round(24+f*20);const dir=i<outwardCount?1:-1;const flow=(((t*.28+p.phase/(Math.PI*2))%1)*2-1)*dir;const rad=1+flow*.16;p.mesh.position.set(rx*outward.x*rad,ry*outward.y*rad,p.depth);p.mesh.material.opacity=.72;}
    for(let i=0;i<energyDots.length;i++){const p=energyDots[i],isEnergy=currentExperiment==='energy',isPhoto=currentExperiment==='photo',isStress=currentExperiment==='stress';const amount=isEnergy?currentOxygen:isPhoto?currentPhotoRate:isStress?currentStressLevel:0;p.mesh.visible=(isEnergy||isPhoto||isStress)&&i<Math.floor(amount/2.3);if(!p.mesh.visible)continue;const origin=isPhoto?(coords[currentCell].chloroplast||[0,0,0]):isStress?coords[currentCell].nucleus:coords[currentCell].mitochondria,pulse=.18+.44*((t*(.18+amount*.004)+p.phase)%1);p.mesh.position.set(origin[0]+Math.cos(p.angle+t*.2)*pulse,origin[1]+Math.sin(p.angle+t*.2)*pulse,origin[2]+Math.sin(t+p.phase)*.25);p.mesh.material.color.set(isPhoto?0xe3d19a:isStress?0xe3a47d:0xf9d9ad);p.mesh.material.opacity=.38+amount/200;}
